let clicks = 0;
const btn = document.getElementById('btn');
const status = document.getElementById('status');

btn?.addEventListener('click', () => {
  clicks += 1;
  if (status) status.textContent = `Clicked ${clicks} time${clicks === 1 ? '' : 's'}!`;
});

